pub fn split(&self, mid: DateTime<Utc>) -> Split<Self> {
    let before = Self::new(self.start, self.end.min(mid));
    let after = Self::new(self.start.max(mid), self.end);
    match (before, after) {
        // PANICS:
        // This will never panic because all constructors enforce start < end
        (None, None) => unreachable!(),
        (Some(before), None) => Split::Before(before),
        (None, Some(after)) => Split::After(after),
        (Some(before), Some(after)) => Split::Both(before, after),
    }
}

pub fn new(start: DateTime<Utc>, end: DateTime<Utc>) -> Option<Self> {
    (start <= end).then_some(Self { start, end })
}

pub fn client<E>(e: E) -> Self
where
    E: Into<InnerError>,
{
    Self {
        inner: Some((Kind::Client, e.into())),
    }
}

fn drop(&mut self) {
    if let Some((kind, e)) = self.inner.take() {
        // TODO: Consider building this into the soft-assert contract
        if std::thread::panicking() {
            error!(?kind, ?e, "AppError dropped without being consumed");
        } else {
            soft_assert_error!(?kind, ?e, "AppError dropped without being consumed");
        }
    }
}

fn from(mut value: AppError) -> Self {
    let (kind, error) = value
        .inner
        .take()
        .expect("AppError inner is always Some until converted");
    match kind {
        Kind::Client => {
            debug!(?error, "Client error");
            Self::new(error.to_string())
        }
        Kind::Server => {
            soft_assert_error!(?error, "Server error");
            // Don't leak potentially sensitive information
            Self::new("Internal server error")
        }
        Kind::Undecided => {
            warn!(?error, "Client or server error (undecided)");
            Self::new(error.to_string())
        }
    }
}

pub fn __should_panic() -> bool {
    static SHOULD_PANIC: OnceLock<bool> = OnceLock::new();
    *SHOULD_PANIC.get_or_init(|| match std::env::var_os("SOFT_ASSERT_PANIC") {
        None => cfg!(debug_assertions),
        Some(s) if s == "auto" => cfg!(debug_assertions),
        Some(s) if s == "always" => true,
        Some(s) if s == "never" => false,
        Some(s) => {
            panic!("Expected SOFT_ASSERT_PANIC to be 'auto', 'always' or 'never', but got {s:?}")
        }
    })
}

fn calculate_backoff_delay(attempt: u32) -> Duration {
    let base_delay = BASE_RETRY_DELAY_MS * (1 << attempt.min(5));
    let delay = base_delay.min(MAX_RETRY_DELAY_MS);
    let jitter = (delay / 4) * (attempt as u64 % 4) / 4;
    Duration::from_millis(delay + jitter)
}

fn calculate_adaptive_poll_interval(record_count: usize, current_interval_ms: u64) -> u64 {
    if record_count >= LOW_RECORD_THRESHOLD {
        // Plenty of data, poll at minimum interval
        MIN_POLL_INTERVAL_MS
    } else if record_count == 0 {
        // No data, back off more aggressively
        ((current_interval_ms as f64) * IDLE_BACKOFF_MULTIPLIER).min(MAX_POLL_INTERVAL_MS as f64)
            as u64
    } else {
        // Some data but not much, slight backoff
        ((current_interval_ms as f64) * 1.2).min(MAX_POLL_INTERVAL_MS as f64) as u64
    }
}

fn parse_raw_records<T: Aggregatable>(
    raw_records: Vec<RawKinesisRecord>,
    shard_id: &str,
) -> Vec<KinesisRecord<T>> {
    raw_records
        .into_iter()
        .filter_map(|raw| {
            let sample: T = match serde_json::from_slice(&raw.data) {
                Ok(s) => s,
                Err(e) => {
                    let data_preview = String::from_utf8_lossy(&raw.data);
                    let preview_truncated: String = data_preview.chars().take(200).collect();
                    warn!(
                        error = %e,
                        data_preview = %preview_truncated,
                        "Failed to deserialize Kinesis record, skipping"
                    );
                    return None;
                }
            };
            let arrival_time = raw
                .approximate_arrival_timestamp
                .and_then(|t| DateTime::from_timestamp(t.secs(), t.subsec_nanos()))
                .unwrap_or_else(Utc::now);

            Some(KinesisRecord {
                sample,
                approximate_arrival_time: arrival_time,
                sequence_number: raw.sequence_number,
                shard_id: shard_id.to_string(),
            })
        })
        .collect()
}

async fn get_shard_iterator_with_retry(
    &self,
    shard_id: &str,
    position: ShardIteratorPosition,
) -> anyhow::Result<String> {
    let mut attempt = 0;

    loop {
        attempt += 1;

        match self
            .reader
            .get_shard_iterator(&self.config.stream_name, shard_id, position.clone())
            .await
        {
            Ok(iterator) => return Ok(iterator),
            Err(e) => {
                if attempt >= MAX_SHARD_ITERATOR_RETRIES {
                    return Err(e);
                }
                let delay = calculate_backoff_delay(attempt);
                warn!(shard_id = %shard_id, attempt, "Retrying get_shard_iterator");
                sleep(delay).await;
            }
        }
    }
}

async fn resolve_target_account(
    describer: &dyn IotDescriber,
    thing_name: &str,
) -> anyhow::Result<Option<String>> {
    let attrs = describer.describe_thing(thing_name).await?;
    Ok(attrs.and_then(|a| a.get("targetAccount").cloned()))
}

async fn describe_thing(
    &self,
    thing_name: &str,
) -> anyhow::Result<Option<HashMap<String, String>>> {
    match self
        .client
        .describe_thing()
        .thing_name(thing_name)
        .send()
        .await
    {
        Ok(response) => Ok(response.attributes),
        Err(err)
            if err.as_service_error().is_some_and(|e| {
                matches!(
                    e,
                    DescribeThingError::ResourceNotFoundException(_)
                        | DescribeThingError::InvalidRequestException(_)
                )
            }) =>
        {
            warn!(thing_name, "Thing not found or invalid, skipping");
            Ok(None)
        }
        Err(err) => Err(err.into()),
    }
}

const getItem = <T,>(key: string, parser: (value: string) => T = JSON.parse) => {
  if (typeof window === 'undefined') {
    return;
  }

  const item = window[storage].getItem(key);

  if (!item) {
    return;
  }

  return parser(item);
};

const reducer = <T extends {}>(state: Record<string, T>, action: { key: string; value: T }) => {
  if (typeof window !== 'undefined') {
    if (action.value === null || action.value === undefined) {
      window[storage].removeItem(action.key);
    } else {
      window[storage].setItem(action.key, JSON.stringify(action.value));
    }
  }

  return {
    ...state,
    [action.key]: action.value,
  };
};

fn charge_insert(&self, bytes: u64) -> bool {
    let Some(high_water) = self.insert_high_water_bytes else {
        return true;
    };
    // Reserve first, then check. Concurrent charges serialize through the
    // reservation counter, so each check sees every earlier in-flight
    // charge; a refused charge rolls its reservation back.
    let outstanding = self
        .reserved_insert_bytes
        .fetch_add(bytes, Ordering::SeqCst);
    if self
        .approx_bytes_cached()
        .saturating_add(outstanding)
        .saturating_add(bytes)
        > high_water
    {
        self.reserved_insert_bytes
            .fetch_sub(bytes, Ordering::SeqCst);
        return false;
    }
    true
}

fn settle_insert_charge(&self, bytes: u64) {
    // With the guard disabled `charge_insert` reserved nothing.
    if self.insert_high_water_bytes.is_some() {
        self.reserved_insert_bytes
            .fetch_sub(bytes, Ordering::SeqCst);
    }
}

async fn run(
    mut self,
) -> DatafusionResult<(
    Vec<RecordBatch>,
    futures::stream::Fuse<SendableRecordBatchStream>,
)> {
    // Only the first poll arms the exit, not construction.
    self.exit.armed = true;

    let mut held = Vec::new();
    while let Some(batch) = self.input.next().await {
        let batch = batch?;
        // A bypassed batch still passes through untouched. Admission decides
        // retention only, never what the query returns.
        let incoming_bytes = batch.get_array_memory_size() as u64;
        if batch.num_rows() != 0 && self.admission.admit(incoming_bytes) {
            let inserted = self.cache.insert_batch_deduplicated(
                Arc::clone(&self.schema),
                self.pk.clone(),
                &batch,
            );
            // Settled before the error propagates, so a failed insert
            // releases its charge too.
            self.cache.settle_insert_charge(incoming_bytes);
            inserted?;
        }
        held.push(batch);
        // `admit` may have just tripped the bypass, and so may another partition
        // sharing this admission state. A bypassed span records neither items
        // nor void, so this partition owes it nothing further.
        if self.admission.bypassed() {
            self.exit.finish(false);
            return Ok((held, self.input));
        }
    }

    self.exit.finish(true);
    Ok((held, self.input))
}

fn drop(&mut self) {
    // A buffered insert interrupted by an error or a cancellation leaves the
    // fetch incomplete, so the partition counts as finished-failed and the
    // span's void is never recorded.
    if self.armed {
        self.tracker.partition_finished(false);
    }
    // Dropped here rather than left to the field, so the release follows the
    // marking above in one readable sequence.
    drop(self.release.take());
}

fn insert_batch_deduplicated(
    &self,
    schema: SchemaRef,
    pk: String,
    batch: &RecordBatch,
) -> DatafusionResult<()> {
    // The weight moka will fold in for this entry, minus the weight it
    // already carries. This is the same delta its weigher computes on replace.
    let mut newly_added_bytes: i64 = 0;
    self.inner
        .entry_by_ref(&pk)
        .and_try_compute_with(|entry| match entry {
            Some(entry) => {
                let existing = entry.into_value();
                let existing_bytes = entry_weight(pk.len(), existing.size_bytes());
                let items_cache = existing.append_batch_deduplicated(batch)?;
                newly_added_bytes = entry_weight(pk.len(), items_cache.size_bytes()) as i64
                    - existing_bytes as i64;

                DatafusionResult::<Op<ItemsCache>>::Ok(Op::Put(items_cache))
            }
            None => {
                let items_cache =
                    ItemsCache::new(Arc::clone(&schema), self.temporal_column.name.clone())
                        .append_batch_deduplicated(batch)?;
                newly_added_bytes = entry_weight(pk.len(), items_cache.size_bytes()) as i64;

                DatafusionResult::<Op<ItemsCache>>::Ok(Op::Put(items_cache))
            }
        })?;

    self.add_weight_delta(newly_added_bytes);
    self.metrics.record_size_bytes(self.approx_bytes_cached());

    Ok(())
}

