fn record_void_range(
    &self,
    schema: SchemaRef,
    pk: &str,
    start_millis: i64,
    end_exclusive_millis: i64,
) {
    let item_span_millis = self.item_span.num_milliseconds();
    // The recorded void grows the entry's weight (`ItemsCache::size_bytes`
    // counts the void `Ranges`); add that delta exactly as an insert does.
    let mut delta: i64 = 0;
    self.inner.entry_by_ref(pk).and_compute_with(|entry| {
        let existing = entry.map(|entry| entry.into_value());
        let existing_bytes = existing
            .as_ref()
            .map_or(0, |items| entry_weight(pk.len(), items.size_bytes()));
        let updated = existing
            .unwrap_or_else(|| ItemsCache::new(schema, self.temporal_column.name.clone()))
            .record_void_range(start_millis, end_exclusive_millis, item_span_millis);
        delta = entry_weight(pk.len(), updated.size_bytes()) as i64 - existing_bytes as i64;
        Op::Put(updated)
    });

    self.add_weight_delta(delta);
    self.metrics.record_size_bytes(self.approx_bytes_cached());
}

fn refresh_live_window_if_stale(
    &self,
    pk: &str,
    live_cutoff: DateTime<Utc>,
    now: DateTime<Utc>,
) -> DatafusionResult<()> {
    let Some(ttl) = self.live_data_ttl else {
        return Ok(());
    };

    {
        let mut refreshed_at = self
            .live_refreshed_at
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let is_fresh = refreshed_at
            .get(pk)
            .is_some_and(|refreshed| now - *refreshed < ttl);
        if is_fresh {
            return Ok(());
        }
        refreshed_at.insert(pk.to_string(), now);
    }

    // Drop the live window (sort keys at/after the cutoff) so the query's
    // normal fetch path repopulates it with fresh data. Rows that have aged
    // below the cutoff are immutable and stay cached — the live tail becomes
    // durable in place.
    //
    // The drop shrinks the entry via `Op::Put`, a `Replaced` the eviction
    // listener skips, so the shrink lands in the total like every other weight
    // change.
    let mut delta: i64 = 0;
    self.inner
        .entry_by_ref(pk)
        .and_try_compute_with(|entry| match entry {
            Some(entry) => {
                let existing = entry.into_value();
                let existing_bytes = entry_weight(pk.len(), existing.size_bytes());
                let retained = existing.retain_older_than(live_cutoff)?;
                delta = entry_weight(pk.len(), retained.size_bytes()) as i64
                    - existing_bytes as i64;
                DatafusionResult::<Op<ItemsCache>>::Ok(Op::Put(retained))
            }
            None => DatafusionResult::<Op<ItemsCache>>::Ok(Op::Nop),
        })?;
    self.add_weight_delta(delta);
    Ok(())
}

