fn execute_coalesced(
    &self,
    partition: usize,
    context: Arc<TaskContext>,
    rx: &tokio::sync::watch::Receiver<Release>,
) -> DatafusionResult<SendableRecordBatchStream> {
    let schema = Arc::clone(&self.input.schema());

    if partition > 0 {
        return Ok(Box::pin(RecordBatchStreamAdapter::new(
            schema,
            futures::stream::empty::<DatafusionResult<_>>(),
        )));
    }

    let cache = Arc::clone(&self.cache);
    let input = Arc::clone(&self.input);
    let pk = self.pk.clone();
    let sk_name = cache.temporal_column().name().to_string();
    let sk_range = self.sk_range.clone();
    let mut rx = rx.clone();

    let stream = futures::stream::once(async move {
        // `Err` means the primary vanished without signalling (its sender was
        // dropped); treat that as unpopulated and fetch ourselves.
        let populated = matches!(
            rx.wait_for(|r| r.is_settled()).await.as_deref(),
            Ok(Release::Populated)
        );

        if populated {
            // The cache compares its native timestamp sort keys, not strings;
            // BETWEEN is inclusive, so the half-open end steps back one grid
            // millisecond.
            let filter = col(&sk_name).between(
                sk_range.start.literal(),
                sk_range.end.last_before().literal(),
            );
            let execution_props = datafusion::execution::context::ExecutionProps::new();
            match cache.filtered_batches(&pk, &[filter], &execution_props) {
                Ok(batches) => {
                    // Trust the read only when the present items plus the
                    // recorded void cover the whole span, never on row
                    // presence alone. `Populated` is latched at the primary's
                    // release for the primary's own span; the coalescing key
                    // floors and ceils to `item_span`, so a waiter with a
                    // wider exact `sk_range` shares the key yet needs rows the
                    // primary never fetched, and the moka entry can be evicted
                    // between release and read. A non-empty but incomplete
                    // read would serve that uncovered tail as absent.
                    match coalesced_read_coverage(
                        &batches,
                        cache.void_ranges(&pk),
                        &sk_name,
                        cache.item_span(),
                    ) {
                        Ok(covered) => {
                            if span_is_fully_covered(covered, &sk_range) {
                                return futures::stream::iter(batches.into_iter().map(Ok))
                                    .boxed();
                            }
                        }
                        Err(e) => return futures::stream::once(async { Err(e) }).boxed(),
                    }
                }
                Err(e) => return futures::stream::once(async { Err(e) }).boxed(),
            }
        }

        // The fetch is not re-keyed. A bypassed or failed fetch never populates
        // the cache, so re-acquiring the coalescing key would serialize the
        // waiters behind an insert none of them could then read, adding latency
        // without saving a backend query. This stream consumes all input
        // partitions because only partition 0 emits for a coalesced instance.
        cache.record_backend_fetch();
        let partitions = input.properties().output_partitioning().partition_count();
        match (0..partitions)
            .map(|p| input.execute(p, Arc::clone(&context)))
            .collect::<DatafusionResult<Vec<_>>>()
        {
            Ok(streams) => futures::stream::select_all(streams).boxed(),
            Err(e) => futures::stream::once(async { Err(e) }).boxed(),
        }
    })
    .flatten();

    Ok(Box::pin(RecordBatchStreamAdapter::new(schema, stream)))
}

export function renderReport(report: Report, verbose: boolean): string {
  if (verbose) {
    return report.rows.map((row) => `${row.path}: ${row.score.toFixed(2)} ${row.reasons.join(', ')}`).join('\n');
  }
  return `${report.rows.length} rows, ${report.flagged} flagged`;
}
